function buildCommand() {
  const __args = [['wiki'], 'Utility', 'Get a quick Wikipedia summary', async ({ sock, from, msg, args }) => {
  const term = args.join(' ');
  if (!term) return sock.sendMessage(from, { text: 'Usage: .wiki Albert Einstein' }, { quoted: msg });
  try {
    const res = await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(term)}`);
    const d = await res.json();
    await sock.sendMessage(from, { text: d.extract || 'No summary found.' }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Wikipedia lookup failed.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
